import Link from 'next/link'; import {getActivePlayers} from '@/services/playerService'; import {playerPositionLabels} from '@/constants/positions';
export const metadata={title:'選手一覧'}; export default function PlayersPage(){const players=getActivePlayers();return <><div className="page-head"><p className="eyebrow">SQUAD</p><h1>選手一覧</h1><p>鹿島アントラーズ 2026 登録メンバー</p></div>{(['GK','DF','MF','FW'] as const).map(pos=><section key={pos}><div className="section-head"><h2>{pos} <small>{playerPositionLabels[pos]}</small></h2></div><div className="player-grid">{players.filter(p=>p.position===pos).map(p=><Link className="player-card" href={`/players/${p.playerId}`} key={p.playerId}><div className="player-no">{p.number}</div><div className="avatar">{p.name.slice(0,1)}</div><h3>{p.name}</h3><p>{p.nameEn}</p><span>プロフィールを見る →</span></Link>)}</div></section>)}</>}
